/**
 * - a sentence is written once across the files the scope's `sentences` names
 * - in a string of code of 6 words, or a line or table cell of prose of 8
 * - a generated file aside; the copies counted, falling only
 */
import fs from 'node:fs';
import path from 'node:path';
import ts from 'typescript';
import { describe, expect, it } from 'vitest';
import { isGenerated } from '../lint/header.ts';
import { scope } from '../../scope.ts';
import { heldToItsCount } from './baseline.ts';
import { filesNamedBy, globsNamingNothing } from './globs.ts';

interface Text {
  readonly path: string;
  readonly text: string;
  readonly isCode: boolean;
}

const IN_CODE = 6;
const IN_PROSE = 8;
// a string short of this is a label, never a sentence
const SHORTEST = 20;
const A_FENCE = /```[\s\S]*?```/g;

// a text's sentences of so many words: whitespace, emphasis and a list's `1.` evened out, a number kept
const sentencesOf = (text: string, words: number): readonly string[] =>
  text
    .split(/(?<=[.!?])\s+/)
    .map((one) =>
      one
        .replace(/\s+/g, ' ')
        .trim()
        .replace(/^(?:[*_>\-\s]|\d+[.)]\s)+/, ''),
    )
    .filter((one) => /[.!?]$/.test(one) && one.split(' ').length >= words);

// a source's strings: the syntax tree's literals, a template without a gap among them
function literalsOf({ path: file, text }: Text): readonly string[] {
  const found: string[] = [];
  const visit = (node: ts.Node): void => {
    if (ts.isStringLiteral(node) || ts.isNoSubstitutionTemplateLiteral(node))
      found.push(node.text);
    ts.forEachChild(node, visit);
  };
  visit(ts.createSourceFile(file, text, ts.ScriptTarget.Latest, true));
  return found;
}

const sentencesIn = (source: Text): readonly string[] =>
  source.isCode
    ? literalsOf(source)
        .filter((literal) => literal.length >= SHORTEST)
        .flatMap((literal) => sentencesOf(literal, IN_CODE))
    : source.text
        .replace(A_FENCE, '')
        .split('\n')
        .flatMap((line) => line.split('|'))
        .flatMap((part) => sentencesOf(part, IN_PROSE));

// each sentence two files or more hold, with those files; a generated file repeats its source, so it is aside
function copiesOf(
  sources: readonly Text[],
): ReadonlyMap<string, readonly string[]> {
  const homes = new Map<string, Set<string>>();
  for (const source of sources.filter(
    (one) => !(one.isCode && isGenerated(one.text)),
  ))
    for (const sentence of sentencesIn(source))
      homes.set(sentence, (homes.get(sentence) ?? new Set()).add(source.path));
  return new Map(
    [...homes]
      .filter(([, files]) => files.size > 1)
      .map(([sentence, files]) => [sentence, [...files].sort()]),
  );
}

const textsOf = (globs: readonly string[], isCode: boolean): readonly Text[] =>
  filesNamedBy(scope, globs).map((file) => ({
    path: file,
    text: fs.readFileSync(path.join(scope.root, file), 'utf8'),
    isCode,
  }));

describe('a sentence is written once', () => {
  it('one sentence in two strings, or two files of prose, is found; a short one and a fenced one are not', () => {
    const said =
      'The document moved while you were reading it, so read it again.';
    const prose =
      'Mark each task in progress when you begin it, and done after.';
    const code = (file: string, literal: string): Text => ({
      path: file,
      text: `export const A = '${literal}';`,
      isCode: true,
    });
    const md = (file: string, text: string): Text => ({
      path: file,
      text,
      isCode: false,
    });
    expect([
      ...copiesOf([
        code('a.ts', said),
        code('b.ts', said),
        code('c.ts', 'Read it again now.'),
        code('d.ts', 'Read it again now.'),
        {
          ...code('e.ts', said),
          text: `// GENERATED by scripts/emit.ts\nexport const A = '${said}';`,
        },
        md('d.md', '1000 words is the cap of a file read every turn.'),
        md('e.md', '2000 words is the cap of a file read every turn.'),
        md('a.md', `# A\n\n1. ${prose}\n`),
        md('b.md', `| Step | ${prose} |\n`),
        md('c.md', `\`\`\`\n${prose}\n\`\`\`\n`),
      ]),
    ]).toEqual([
      [said, ['a.ts', 'b.ts']],
      [prose, ['a.md', 'b.md']],
    ]);
  });

  it('each glob of the scope names a file', () => {
    const { code, prose } = scope.sentences;
    expect({
      code: globsNamingNothing(scope, code),
      prose: globsNamingNothing(scope, prose),
    }).toEqual({ code: [], prose: [] });
  });

  it('no sentence gains a copy beyond its baseline, each copy counted', () => {
    const copies = copiesOf([
      ...textsOf(scope.sentences.code, true),
      ...textsOf(scope.sentences.prose, false),
    ]);
    expect(
      heldToItsCount(
        'aSentenceIsWrittenOnce',
        new Map(
          [...copies].map(([sentence, files]) => [sentence, files.length]),
        ),
      ),
      [...copies]
        .map(([sentence, files]) => `${files.join(' · ')} · ${sentence}`)
        .join('\n'),
    ).toEqual({ added: [], fixed: [] });
  });
});
